using System;using System.IO;using System.Linq;using System.Text;using System.Drawing;using System.Windows.Forms;using System.Threading.Tasks;using System.Collections.Generic;using System.Text.RegularExpressions;
namespace Ara {
 public sealed class NotionConnectWindow:Form {
  readonly NotionHub hub;readonly string directory;Label status;TextBox query,link,output;ListBox results;bool busy;string messageAfterCreate="";object[] tools;System.Windows.Forms.Timer timer;string selectedTitle="";
  public NotionConnectWindow(MainForm owner){hub=owner.Hub;directory=Path.GetDirectoryName(owner.Store.PathName);Text="노션 연결 · 저장 위치";Size=new Size(680,660);MinimumSize=new Size(620,580);StartPosition=FormStartPosition.CenterParent;
   var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(16),ColumnCount=1,RowCount=10};foreach(int h in new[]{60,44,46,42,140,38,60,44,-1,44})layout.RowStyles.Add(new RowStyle(h<0?SizeType.Percent:SizeType.Absolute,h<0?100:h));Controls.Add(layout);
   status=Theme.Label("연결 상태 확인 중");layout.Controls.Add(status,0,0);var auth=new FlowLayoutPanel{Dock=DockStyle.Fill};Add(auth,"노션 연결",async()=>{await Task.Run(()=>hub.Request(JsonMap.Obj("op","connect")));RefreshStatus();});Add(auth,"연결 상태 확인",()=>{RefreshStatus();return Task.FromResult(0);});layout.Controls.Add(auth,0,1);
   layout.Controls.Add(Theme.Label("로그인·허용 후 저장할 페이지를 고릅니다. 하루 한 행 · 날짜는 기상일 기준입니다.\n이번 단계는 연결과 저장 위치 설정이며, 시간표 자동 동기화는 아직 켜지지 않습니다.",9),0,2);
   var search=new FlowLayoutPanel{Dock=DockStyle.Fill};query=new TextBox{Width=300,AccessibleName="저장할 노션 페이지 검색"};search.Controls.Add(query);Add(search,"페이지 찾기",Search);layout.Controls.Add(search,0,3);results=new ListBox{Dock=DockStyle.Fill};results.SelectedIndexChanged+=(s,e)=>{var row=results.SelectedItem as HubRow;if(row!=null){link.Text=row.id;selectedTitle=row.title;}};layout.Controls.Add(results,0,4);
   link=new TextBox{Dock=DockStyle.Fill,AccessibleName="노션 페이지 또는 기존 데이터베이스 링크"};layout.Controls.Add(link,0,5);layout.Controls.Add(Theme.Label("날짜 · 제목 · 집중도(0~5) · 만족도(0~5) · 집중 총점 · 기록 시간(분)\n집중도·만족도는 기록 시간에 따른 가중평균, 집중 총점은 점수 × 10분 칸 수입니다.",9),0,6);
   var setup=new FlowLayoutPanel{Dock=DockStyle.Fill};Add(setup,"이 페이지 안에 하루 기록 DB 만들기",Create);Add(setup,"기존 DB를 저장 위치로",Existing);layout.Controls.Add(setup,0,7);output=new TextBox{Dock=DockStyle.Fill,ReadOnly=true,Multiline=true,ScrollBars=ScrollBars.Vertical,AccessibleName="노션 설정 결과"};layout.Controls.Add(output,0,8);var foot=new FlowLayoutPanel{Dock=DockStyle.Fill};Add(foot,"이 기기의 연결 해제",async()=>{await Task.Run(()=>hub.Request(JsonMap.Obj("op","disconnect")));tools=null;RefreshStatus();});Add(foot,"기존 PC AI 정리 (고급)",()=>{using(var advanced=new NotionWindow(owner))advanced.ShowDialog(this);return Task.FromResult(0);});layout.Controls.Add(foot,0,9);
   timer=new System.Windows.Forms.Timer{Interval=2500};timer.Tick+=(s,e)=>{if(!busy)RefreshStatus();};timer.Start();FormClosed+=(s,e)=>timer.Dispose();FormClosing+=(s,e)=>{if(busy)e.Cancel=true;};RefreshStatus();Theme.Apply(this);
  }
  sealed class HubRow{public string id,title;public override string ToString(){return title;}}
  void Add(FlowLayoutPanel root,string label,Func<Task> action){root.Controls.Add(Theme.Button(label,async(s,e)=>{if(busy)return;busy=true;try{await action();}catch(Exception error){output.Text=error.Message;}finally{busy=false;RefreshStatus();}}));}
  void RefreshStatus(){var value=JsonMap.Map(hub.Request(JsonMap.Obj("op","status")));status.Text=(JsonMap.Str(value,"connected")=="True"?"노션 연결됨":"노션 연결 필요")+" · "+JsonMap.Str(value,"workspace")+"\n저장: "+JsonMap.Str(JsonMap.Child(value,"target"),"title")+" · "+JsonMap.Str(value,"message");}
  public static Dictionary<string,object> Decode(Dictionary<string,object> result){if(JsonMap.Str(result,"isError")=="True")throw new InvalidOperationException("노션 작업을 완료하지 못했습니다. 권한과 연결 상태를 확인해 주세요.");if(result.ContainsKey("structuredContent"))return JsonMap.Child(result,"structuredContent");string text=string.Join("\n",JsonMap.Items(result,"content").Select(x=>JsonMap.Str(JsonMap.Map(x),"text")));try{return JsonMap.Read(text);}catch{return JsonMap.Obj("text",text);}}
  Dictionary<string,object> Tool(string suffix){if(tools==null)tools=JsonMap.Items(JsonMap.Map(hub.Request(JsonMap.Obj("op","tools"))),"tools");var tool=tools.Select(JsonMap.Map).FirstOrDefault(x=>{string n=JsonMap.Str(x,"name").Replace('_','-');return n==suffix||n=="notion-"+suffix;});if(tool==null)throw new InvalidOperationException("현재 노션 계정에서 "+suffix+" 기능을 사용할 수 없습니다.");return tool;}
  Dictionary<string,object> Call(string suffix,object args){return Decode(JsonMap.Map(hub.Request(JsonMap.Obj("op","call","name",JsonMap.Str(Tool(suffix),"name"),"arguments",args))));}
  async Task Search(){string text=query.Text.Trim();if(text.Length==0)throw new InvalidOperationException("페이지 제목을 입력해 주세요.");var value=await Task.Run(()=>Call("search",JsonMap.Obj("query",text,"query_type","internal","page_size",20)));results.Items.Clear();foreach(var item in JsonMap.Items(value,"results")){var row=JsonMap.Map(item);if(JsonMap.Str(row,"type")=="page")results.Items.Add(new HubRow{id=JsonMap.Str(row,"id"),title=JsonMap.Str(row,"title")});}output.Text=results.Items.Count==0?"검색 결과가 없습니다. 노션 페이지 링크를 직접 입력할 수도 있습니다.":"페이지를 고르고 데이터베이스 만들기를 누르세요.";}
  public const string Schema="CREATE TABLE (\"제목\" TITLE, \"날짜\" DATE COMMENT '기상한 날짜 기준', \"집중도\" NUMBER COMMENT '기록 시간으로 가중한 평균 0~5', \"만족도\" NUMBER COMMENT '기록 시간으로 가중한 평균 0~5', \"집중 총점\" NUMBER COMMENT '집중도 곱하기 10분 칸 수 합계', \"기록 시간(분)\" NUMBER)";
  public static Dictionary<string,object> Destination(Dictionary<string,object> data){string raw=JsonMap.Write(data),text=JsonMap.Str(data,"text");var source=Regex.Match(raw,@"collection://([a-fA-F0-9-]{32,36})");string id=source.Success?source.Groups[1].Value:JsonMap.Str(data,"database_id");if(id.Length==0)id=JsonMap.Str(data,"id");if(id.Length==0){var match=Regex.Match(text,"<database[^>]*url=\"[^\"]*?([a-fA-F0-9-]{32,36})(?:[^a-fA-F0-9-]|$)");if(match.Success)id=match.Groups[1].Value;}return JsonMap.Obj("id",NotionService.Id(id),"kind",source.Success?"data_source":"database","title",JsonMap.Str(data,"title").Length>0?JsonMap.Str(data,"title"):"ARA 하루 기록");}
  async Task Create(){string parent=NotionService.Id(link.Text),title=selectedTitle;string marker=Path.Combine(directory,"notion-create-"+parent+".json");if(File.Exists(marker))throw new InvalidOperationException("이 페이지의 생성 요청 이력이 있습니다. 노션에서 생성 여부를 확인한 뒤 기존 DB 링크로 지정해 주세요.");await Task.Run(()=>{var page=Call("fetch",JsonMap.Obj("id",parent));if(!JsonMap.Str(page,"text").Contains("<page")&&(JsonMap.Str(page,"text").Contains("<database")||JsonMap.Str(page,"text").Contains("<data-source")))throw new InvalidOperationException("상위 페이지를 선택해 주세요.");if(!JsonMap.Child(JsonMap.Child(Tool("create-database"),"inputSchema"),"properties").ContainsKey("schema"))throw new InvalidOperationException("현재 노션 연결은 이 데이터베이스 생성 형식을 지원하지 않습니다.");JsonMap.Atomic(marker,JsonMap.Write(JsonMap.Obj("status","requested","parent",parent)));var created=Call("create-database",JsonMap.Obj("parent",JsonMap.Obj("page_id",parent),"title","ARA 하루 기록","schema",Schema,"description","기상일 기준 하루 기록 · ARA 앱의 집중·만족도 요약"));JsonMap.Atomic(marker,JsonMap.Write(JsonMap.Obj("status","created","result",created)));var target=Destination(created);target["parentId"]=parent;target["parentTitle"]=title;hub.Request(JsonMap.Obj("op","target","target",target));if(JsonMap.Str(target,"kind")=="data_source"){try{var found=Regex.Match(JsonMap.Str(created,"text"),"<database[^>]*url=\"[^\"]*?([a-fA-F0-9-]{32,36})");if(!found.Success)throw new InvalidOperationException("DB ID 확인 필요");Call("create-view",JsonMap.Obj("database_id",NotionService.Id(found.Groups[1].Value),"data_source_id",target["id"],"name","날짜별 기록","type","table","configure","SHOW \"날짜\", \"제목\", \"집중도\", \"만족도\", \"집중 총점\", \"기록 시간(분)\"; SORT BY \"날짜\" DESC"));}catch{messageAfterCreate="DB는 저장했습니다. 날짜별 보기 설정은 확인이 필요합니다.";}}});output.Text="하루 기록 데이터베이스를 만들고 저장 위치로 지정했습니다. 자동 시간표 동기화는 아직 켜지지 않았습니다.\r\n"+messageAfterCreate;}
  async Task Existing(){string id=NotionService.Id(link.Text);await Task.Run(()=>{var data=Call("fetch",JsonMap.Obj("id",id));string text=JsonMap.Str(data,"text");if((text.Contains("<page")||!text.Contains("<database")&&!text.Contains("<data-source"))||!new[]{"제목","날짜","집중도","만족도"}.All(text.Contains))throw new InvalidOperationException("제목·날짜·집중도·만족도 속성이 있는 하루 기록 DB 링크를 입력해 주세요.");hub.Request(JsonMap.Obj("op","target","target",Destination(data)));});output.Text="저장 위치를 지정했습니다.";}
 }
}
